				updateHeaders: (configId, headers, skipReconnect) => this.updateHeaders(configId, headers, skipReconnect),
				disconnect: (configId) => this.disconnect(configId),
				getTokenFilePath: (_configId, connectorName) => this.getServerSideOauthTokenFilePath(connectorName)
