				PLAN_MIGRATION_META_KEY,
				LEGACY_TODOS_MIGRATION_META_KEY,
				BRAIN_MIGRATION_META_KEY,
				MEDIA_INDEX_MIGRATION_META_KEY,
				LOCALSTORAGE_MIGRATION_META_KEY,
				CLAW_SETTINGS_MIGRATION_META_KEY,
				MCP_OAUTH_MIGRATION_META_KEY
