/**
* 提取 Prompt 模板内容
*/
function extractPromptContent(content) {
	const lines = content.split("\n");
	let startIndex = 0;
	for (let i = 0; i < lines.length; i++) if (lines[i].includes("Prompt Template")) {
		startIndex = i + 1;
		break;
	}
	return lines.slice(startIndex).join("\n").trim();
}
/**
* 获取 Prompt
*
* @param name Prompt 名称（如 "session-summary.tpl"）
* @returns Prompt 内容
*/
function getPrompt(name) {
	const template = TEMPLATES[name];
	if (!template) throw new Error(`Unknown prompt template: ${name}`);
	return extractPromptContent(template);
}
