//#region src/main/mcp/tools/preview-url-tool.ts
/**
* 单次探测 localhost URL 是否可达（HEAD 请求，2s 超时）
*/
function probeOnce(url) {
	return new Promise((resolve) => {
		try {
			const req = (new URL(url).protocol === "https:" ? https : http).request(url, {
				method: "HEAD",
				timeout: 2e3
			}, (res) => {
				res.resume();
				resolve(true);
			});
			req.on("error", () => resolve(false));
			req.on("timeout", () => {
				req.destroy();
				resolve(false);
			});
			req.end();
		} catch {
			resolve(false);
		}
	});
}
function sleep(ms) {
	return new Promise((resolve) => setTimeout(resolve, ms));
}
/**
* 带重试的 localhost 可达性探测
* 最多尝试 maxRetries+1 次，每次间隔 retryDelayMs
* 用于应对 LLM 刚用 Bash 起了 server 但还没就绪的情况
*/
async function isLocalhostReachable(url, maxRetries = 2, retryDelayMs = 1500) {
	for (let attempt = 0; attempt <= maxRetries; attempt++) {
		if (await probeOnce(url)) return true;
		if (attempt < maxRetries) {
			console.log(`[preview-url] localhost probe attempt ${attempt + 1} failed, retrying in ${retryDelayMs}ms...`);
			await sleep(retryDelayMs);
		}
	}
	return false;
}
/**
* 尝试从 localhost URL 的 pathname 推断本地文件路径
* 例如 http://localhost:8080/cosmos.html + cwd=/Users/foo/bar → /Users/foo/bar/cosmos.html
*/
function tryResolveLocalFile(url, cwd) {
	try {
		const parsed = new URL(url);
		const pathname = decodeURIComponent(parsed.pathname);
		if (!pathname || pathname === "/") return;
		const relativePath = pathname.startsWith("/") ? pathname.slice(1) : pathname;
		if (!relativePath) return;
		if (cwd) {
			const fullPath = path.join(cwd, relativePath);
			try {
				if (require("fs").existsSync(fullPath)) return fullPath;
			} catch {}
		}
		return;
	} catch {
		return;
	}
}
/**
* URL 黑名单检查（与原版 UrlContentFetcher.isBlacklist 逻辑一致）
*/
async function isBlacklist(url, productManager) {
	try {
		const configuration = await Promise.race([productManager.waitConfiguration(), new Promise((resolve) => setTimeout(() => resolve(void 0), 3e3))]);
		if (!configuration) {
			console.warn("[preview-url] Blacklist check skipped: configuration not available within 3s timeout");
			return false;
		}
		const blacklistURLs = (configuration?.config)?.blacklistURLs;
		const blacklistDomains = (configuration?.config)?.blacklistDomains;
		const normalizedUrl = url.trim();
		const hostname = new URL(normalizedUrl).hostname.toLowerCase();
		const isUrlBlocked = Array.isArray(blacklistURLs) && blacklistURLs.some((item) => typeof item === "string" && item.trim().toLowerCase() === normalizedUrl.toLowerCase());
		const isDomainBlocked = Array.isArray(blacklistDomains) && blacklistDomains.some((domain) => {
			if (typeof domain !== "string") return false;
			const targetDomain = domain.trim().toLowerCase();
			return targetDomain && hostname === targetDomain;
		});
		return isUrlBlocked || isDomainBlocked;
	} catch (error) {
		console.warn("[preview-url] Blacklist check failed, allowing URL:", error);
		return false;
	}
}
function createPreviewUrlTool(deps) {
	const { productManager, pushSessionCommand } = deps;
	return {
		name: "preview_url",
		description: "Preview a URL or local file in the desktop application's built-in browser panel. Accepts http/https URLs for remote pages, localhost URLs for local servers, or absolute file paths for local files. For simple static HTML files that don't need a server, prefer passing the absolute file path directly (e.g., /path/to/file.html). For localhost URLs, ensure the server is running first (use the Bash tool to start it). The tool will verify localhost reachability and return actionable guidance if the server is not running.",
		inputSchema: {
			type: "object",
			properties: {
				url: {
					type: "string",
					description: "The URL or file path to preview. For local files: use the absolute file path (e.g., /Users/foo/index.html) — it will be automatically converted to file:// URI. For local servers you started: use the localhost URL (e.g., http://localhost:8080). For remote pages: use a full HTTP/HTTPS URL."
				},
				cwd: {
					type: "string",
					description: "The current working directory (absolute path). Recommended for all preview URLs so the desktop app can route the preview to the owning session. Required when using a localhost URL so the tool can locate local files as fallback if the server is not reachable."
				},
				explanation: {
					type: "string",
					description: "One sentence explanation as to why this tool is being used."
				}
			},
			required: ["url"]
		},
		handler: async (args) => {
			const url = args.url;
			const argCwd = args.cwd;
			if (!url) return {
				content: [{
					type: "text",
					text: "Error: url parameter is required"
				}],
				isError: true
			};
			const isAbsolutePath = path.isAbsolute(url);
			const isFileUri = url.startsWith("file://");
			const isHttpUri = /^https?:\/\//i.test(url);
			if (!isAbsolutePath && !isFileUri && !isHttpUri) return {
				content: [{
					type: "text",
					text: `Error: Unsupported URL. Only http/https URLs, file:// URIs, and absolute file paths are accepted. Got: ${url}`
				}],
				isError: true
			};
			let previewUrl;
			if (isAbsolutePath) previewUrl = `file://${url}`;
			else if (isFileUri) previewUrl = url;
			else {
				let parsedUrl;
				try {
					parsedUrl = new URL(url);
				} catch {
					return {
						content: [{
							type: "text",
							text: `Error: Invalid URL format: ${url}`
						}],
						isError: true
					};
				}
				if (parsedUrl.protocol !== "http:" && parsedUrl.protocol !== "https:") return {
					content: [{
						type: "text",
						text: `Error: Unsupported protocol: ${parsedUrl.protocol}. Accepted: http/https URLs or local file paths.`
					}],
					isError: true
				};
				if (await isBlacklist(url, productManager)) return {
					content: [{
						type: "text",
						text: `Error: IMPORTANT: Current URL is high risk! This ${url} is blocked!`
					}],
					isError: true
				};
				const hostname = parsedUrl.hostname.toLowerCase();
				if (hostname === "localhost" || hostname === "127.0.0.1") if (!await isLocalhostReachable(url)) {
					const port = parsedUrl.port || (parsedUrl.protocol === "https:" ? "443" : "80");
					const pathname = decodeURIComponent(parsedUrl.pathname);
					const localFile = tryResolveLocalFile(url, argCwd);
					const lines = [
						`Error: ${url} is not reachable — no server is running on port ${port}.`,
						"",
						"To preview this URL, you need to start a local server first using the Bash tool.",
						"",
						"Suggested actions:"
					];
					if (localFile) lines.push(`  1. The file exists at: ${localFile}`, "  2. Start a server in that directory, for example:", `     cd ${argCwd} && python3 -m http.server ${port}`, `     or: cd ${argCwd} && npx serve -l ${port}`, `  3. Then call preview_url again with ${url}`, "", `  Alternatively, if the file is a simple static HTML with no JS fetch/routing, you can pass the absolute file path directly: ${localFile}`);
					else if (argCwd) lines.push(`  1. No file matching pathname "${pathname}" found in ${argCwd}`, "  2. Start a server in your working directory:", `     cd ${argCwd} && python3 -m http.server ${port}`, `     or: cd ${argCwd} && npx serve -l ${port}`, "  3. Then call preview_url again with the correct URL");
					else lines.push("  1. Start a local server using the Bash tool (e.g., python3 -m http.server or npx serve)", `  2. Make sure it listens on port ${port}`, "  3. Then call preview_url again with the server URL");
					return {
						content: [{
							type: "text",
							text: lines.join("\n")
						}],
						isError: true
					};
				} else previewUrl = url;
				else previewUrl = url;
			}
			pushSessionCommand("openBrowser", {
				url: previewUrl,
				cwd: argCwd
			});
			return { content: [{
				type: "text",
				text: JSON.stringify({
					type: "preview_tool_result",
					url: previewUrl,
					message: `success to open preview url: ${previewUrl}`
				})
			}] };
		}
	};
}
