	server.handle("claw:getLatestSession", async () => {
		const latest = (await getClawService()).getLatestActiveConversation();
		return latest ? {
			sessionId: latest.agentSessionId,
			cwd: latest.cwd
		} : {
			sessionId: null,
			cwd: null
		};
	});
	server.handle("claw:notifySessionActive", async (...args) => {
		const params = args[0];
		if (!params?.sessionId || !params?.cwd) return;
		(await getClawService()).notifyClawSessionActive(params.sessionId, params.cwd);
	});
