function createPowerManager(options = {}) {
	const blocker = options.powerSaveBlocker ?? electron.powerSaveBlocker;
	const logger = options.logger ?? console;
	let blockerId = null;
	let enabled = false;
	return {
		setEnabled(nextEnabled) {
			enabled = nextEnabled;
			if (enabled) {
				if (blockerId !== null) return;
				blockerId = blocker.start("prevent-display-sleep");
				logger.info?.("[PowerManager] Started power save blocker", { blockerId });
				return;
			}
			if (blockerId === null) return;
			blocker.stop(blockerId);
			logger.info?.("[PowerManager] Stopped power save blocker", { blockerId });
			blockerId = null;
		},
		isEnabled() {
			return enabled;
		},
		isActive() {
			return blockerId !== null && blocker.isStarted(blockerId);
		},
		cleanup() {
			if (blockerId === null) {
				enabled = false;
				return;
			}
			blocker.stop(blockerId);
			logger.info?.("[PowerManager] Cleaned up power save blocker", { blockerId });
			blockerId = null;
			enabled = false;
		}
	};
}
